using System;

class Program
{
    const long M = 4294967296L;

    // Mix flow id a with backend b into a 32-bit value
    static long H(long a, long b)
    {
        long x = (a * 2654435761L + b * 40503L + 17) % M;
        x ^= x >> 15;
        x = (x * 40503L) % M;
        x ^= x >> 13;
        return x;
    }

    static int ModPick(int f, int[] bs)
    {
        return bs[(int)(H(f, 0) % bs.Length)];
    }

    static int RendezvousPick(int f, int[] bs)
    {
        int best = bs[0];
        foreach (int b in bs)            // backend with the highest score wins
            if (H(f, b + 1) > H(f, best + 1)) best = b;
        return best;
    }

    static void Main()
    {
        int[] before = { 0, 1, 2, 3 };
        int[] after = { 0, 1, 2 };
        int modMoved = 0, rdvMoved = 0, onDead = 0;
        for (int f = 0; f < 1000; f++)
        {
            if (ModPick(f, before) != ModPick(f, after)) modMoved++;
            if (RendezvousPick(f, before) != RendezvousPick(f, after)) rdvMoved++;
            if (RendezvousPick(f, before) == 3) onDead++;
        }
        Console.WriteLine("flows: 1000 backends 4 -> 3");
        Console.WriteLine("mod N moved: " + modMoved);
        Console.WriteLine("rendezvous moved: " + rdvMoved + " (flows that were on the dead backend: " + onDead + " )");
    }
}
